 const stale=data?.error||data&&Date.now()-data.checkedAt>20*60*1000;
 const label=!source?'Not reported for this location':!data?'Loading fire danger…':data.error&&!data.features.length?'Fire danger unavailable':matches.length?matches.map(f=>f.properties.level).join(' / '):'Not reported for this location';
