if(Object.hasOwn(feedLabels,savedFilters.feedKind))state.feedKind=savedFilters.feedKind;
let feedSort=savedFilters.feedSort==='trip'?'trip':'newest';
function closeFeed(){$('#trail-feed').hidden=true;$('#updates-button').setAttribute('aria-expanded','false')}
function renderFeed(){saveFilters();refreshFeed();const panel=$('#trail-feed');panel.hidden=false;$('#updates-button').setAttribute('aria-expanded','true');if(!panel.dataset.ready){panel.dataset.ready='true';panel.innerHTML=`<header class="trail-feed-header"><div><span class="eyebrow">OUTZIDE COMMUNITY</span><h2 id="trail-feed-title">Field feed</h2></div><button type="button" id="close-feed" aria-label="Close field feed">×</button></header><div class="trail-feed-controls"><label>Show<select id="feed-filter">${Object.entries(feedLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Sort<select id="feed-sort"><option value="newest">Newest posts</option><option value="trip">Upcoming trips</option></select></label></div><p class="feed-local-note">Posts are shared with the Outzide community. Sign in to post or reply.</p><div id="field-feed-items" aria-live="polite"></div><form id="field-feed-compose"><details><summary>Write a post or arrange a ride</summary><div class="feed-form-grid"><label class="wide">Destination<select name="place" required><option value="" ${!state.selected?'selected':''}>Decide together · no destination yet</option>${[...places].sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${esc(p.id)}" ${state.selected?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Post type<select name="kind"><option value="TRIP_NOTE">Trail note</option><option value="LOOKING_FOR_COMPANY">Find company</option><option value="HIKE_BUDDY">Find a hike buddy</option><option value="CAMP_BUDDY">Find a camp buddy</option><option value="CARPOOL_OFFER">Offer a ride</option><option value="CARPOOL_REQUEST">Request a ride</option></select></label><label><span id="feed-date-label">Trip date</span><input name="date" type="date" min="${today()}" value="${today()}" required></label><label class="wide" id="feed-area-field" hidden>Preferred area (optional)<input name="area" maxlength="100" placeholder="Near Portland, coast, open to ideas…"></label><label class="wide">Leaving from <span>(optional)</span><input name="departure" maxlength="100" placeholder="Town or general meeting area"></label></div></details><label class="sr-only" for="field-post-body">Your field feed post</label><div class="field-feed-send"><textarea id="field-post-body" name="body" maxlength="500" rows="2" placeholder="Share a trail update, offer a ride, or find one…" required></textarea><button class="primary" type="submit" aria-label="Post to field feed">↑</button></div></form>`;$('#field-feed-compose select[name="kind"]').onchange=()=>{const f=$('#field-feed-compose'),buddy=['HIKE_BUDDY','CAMP_BUDDY'].includes(f.elements.kind.value);f.elements.place.required=!buddy;f.elements.date.required=!buddy;$('#feed-area-field').hidden=!buddy;$('#feed-date-label').textContent=buddy?'Trip date (optional / flexible)':'Trip date';if(buddy){f.elements.date.value='';f.elements.place.value=''}};$('#close-feed').onclick=()=>{closeFeed();$('#updates-button').focus()};$('#feed-filter').onchange=e=>{state.feedKind=e.target.value;saveFilters();renderFeedItems()};$('#feed-sort').onchange=e=>{feedSort=e.target.value;saveFilters();renderFeedItems()}}$('#feed-filter').value=state.feedKind;$('#feed-sort').value=feedSort;renderFeedItems();if(!panel.querySelector('.drawer-handle'))installMobileDrawer(panel,closeFeed,'field feed')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-field-place],[data-field-wall]');if(!b)return;closeFeed();selectPlace(b.dataset.fieldPlace||b.dataset.fieldWall);if(b.dataset.fieldWall)changeTab('community')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#trail-feed').hidden){closeFeed();$('#updates-button').focus()}});

// All commands share the same visible interaction handlers, including WebMCP below.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select){selectPlace(b.dataset.select);return}if(b.dataset.region){state.browseRegion=null;state.region=b.dataset.region;closeDetail({clear:true});renderList();fitRegion();return}if(b.dataset.kind){state.activities=[];state.kind=b.dataset.kind;closeDetail({clear:true});renderList();return}if(b.dataset.view){if(b.classList.contains('browse-toggle'))openBrowse();else setView(b.dataset.view);return}if(b.dataset.tab||b.dataset.openTab){changeTab(b.dataset.tab||b.dataset.openTab);return}if(b.dataset.feedKind){state.feedKind=b.dataset.feedKind;renderFeed();return}if(b.dataset.feedPlace){$('#utility').close();selectPlace(b.dataset.feedPlace);changeTab('community');return}const p=state.selected,c=p&&community(p.id);if(b.dataset.removeDate){state.tripDates=state.tripDates.filter(d=>d!==b.dataset.removeDate);if(!state.tripDates.length)state.tripDates=[today()];renderDetail();return}if(b.dataset.editPost!=null){state.editPost=Number(b.dataset.editPost);renderDetail();return}
 switch(b.dataset.action){case'refresh-fire':refreshFire();break;case'clear-filters':resetFilters();break;case'close-detail':closeDetail({clear:true});break;case'minimize':closeDetail();break;case'reopen-detail':renderDetail();$('#detail').show();$('#selection-dock').hidden=true;break;case'explore-route':showRoute(p);closeDetail();break;case'fit-route':showRoute(p);break;case'locate-detail':locate();break;case'refresh-weather':refreshWeather();break;case'refresh-beach':refreshBeach();break;case'cancel-edit':state.editPost=null;renderDetail();break;case'add-date':{const d=$('#trip-date').value;if(!d||d<today()){toast('Choose today or a future date.');break}if(!state.tripDates.includes(d))state.tripDates.push(d);renderDetail();break}case'outdoor-updates':renderFeed();break;}});
function resetFilters(){state.region='all';state.browseRegion=null;state.activities=[];state.kind='all';state.query='';$('#search').value='';renderList()}
$('#search').addEventListener('input',e=>{state.query=e.target.value;closeDetail({clear:true});renderList()});$('#reset-filters').onclick=resetFilters;$('#updates-button').onclick=()=>$('#trail-feed').hidden?renderFeed():closeFeed();$('#sources-button').onclick=sources;$('.utility-close').onclick=()=>$('#utility').close();$('#utility').addEventListener('click',e=>{if(e.target===$('#utility')){const r=$('#utility').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#utility').close()}});$('#terrain-toggle').onclick=()=>{const tilt=map.getPitch()<10;map.easeTo({pitch:tilt?55:0,duration:500});$('#terrain-toggle').setAttribute('aria-pressed',String(tilt));};$('#locate').onclick=locate;$('#zoom-in').onclick=()=>map.zoomIn();$('#zoom-out').onclick=()=>map.zoomOut();$('#retry-map').onclick=()=>{location.reload()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#detail').open&&!$('#utility').open){closeDetail({clear:true});e.preventDefault()}if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();showBrowseStep('results');setView('list');$('#search').focus()}if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['overview','conditions','community'],i=tabs.indexOf(state.tab),next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;changeTab(tabs[next])}});
async function init(){try{const data=await Promise.all(['places.json','details.json','routes.json','states.json','feed.json','beaches.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error(path);return r.json()}));[metadata,details,routes,,feed,beaches]=data;places=metadata.places.map(p=>{if(p.routeIds&&!p.routeMatch){const clean={...p};for(const key of ['routeIds','routeName','routeMiles','routeSurface','routeGrade'])delete clean[key];return clean}return p});$('#snapshot-date').textContent='Captured '+stamp(metadata.fetchedAt);const elevation=new mlcontour.DemSource({id:'outz-elevation',url:'https://tiles.mapterhorn.com/{z}/{x}/{y}.webp',encoding:'terrarium',maxzoom:13,worker:true,cacheSize:64});elevation.setupMaplibre(maplibregl);const style=mapzSurfaceStyle({terrainStrength:1,demTiles:[elevation.sharedDemProtocolUrl],contourTiles:[elevation.contourProtocolUrl({multiplier:3.28084,thresholds:{10:[500,2000],12:[100,500],14:[50,200],15:[20,100]},contourLayer:'contours',elevationKey:'ele',levelKey:'level'})]});
style.sources.relief=structuredClone(style.sources.elevation);style.layers.find(l=>l.id==='land-relief').source='relief';style.glyphs='https://tiles.openfreemap.org/fonts/{fontstack}/{range}.pbf';style.layers.push({id:'osm-trails',type:'line',source:'terrain','source-layer':'transportation',minzoom:10,filter:['==',['get','class'],'path'],paint:{'line-color':'#9bbaa2','line-opacity':.65,'line-width':['interpolate',['linear'],['zoom'],10,.7,16,2],'line-dasharray':[3,2]}},{id:'place-labels',type:'symbol',source:'terrain','source-layer':'place',layout:{'text-field':['coalesce',['get','name:en'],['get','name']],'text-font':['Noto Sans Regular'],'text-size':['interpolate',['linear'],['zoom'],5,11,12,15]},paint:{'text-color':'#b9cccd','text-halo-color':'#080c0c','text-halo-width':2}});
try{const r=await fetch('i5-route.json');if(!r.ok)throw Error('I-5 geometry unavailable');addI5Spectrum(style,await r.json())}catch(error){console.warn(error)}
const savedCamera=readSavedCamera();addCascadiaOutline(style);map=new maplibregl.Map({container:'map',style,center:[-120.5,44.1],zoom:6,minZoom:CASCADIA_MIN_ZOOM,maxZoom:18,maxPitch:75,pitch:35,...(savedCamera||{}),attributionControl:{compact:true}});installCascadiaReveal(map,places);map.addControl(new maplibregl.NavigationControl({showZoom:false,visualizePitch:true}),'bottom-right');canvas=document.createElement('canvas');canvas.className='hologram-canvas';canvas.setAttribute('aria-hidden','true');$('#map').append(canvas);ctx=canvas.getContext('2d');materials=createHologramMaterials([...new Set(['#D95757','#F2EBDD',...places.map(p=>p.accent.toUpperCase())])]);waterBloom=createWaterBloom();map.on('render',drawHolograms);map.on('sourcedata',()=>waterBloom.invalidate());map.on('error',e=>{console.warn('Map source:',e.error?.message);if(!map.loaded())$('#map-failure').hidden=false});map.on('movestart',()=>{terrainReady=false});map.on('moveend',renderMarkers);map.on('resize',renderMarkers);map.on('idle',()=>{terrainReady=true;$('#map-failure').hidden=true;markers.forEach(m=>m.setLngLat([m.place.lng,m.place.lat]));drawHolograms();updateElevation()});new ResizeObserver(()=>map.resize()).observe($('#map'));await new Promise(resolve=>map.on('load',resolve));setView('map');if(!savedCamera)fitRegion(startingBounds);rememberMapCamera(map);$('#terrain-toggle').setAttribute('aria-pressed',String(map.getPitch()>=10));renderList();registerTools();refreshWinterEvents().then(()=>{renderMarkers();if(state.selected?.kind==='winter')renderDetail()});setInterval(()=>refreshWinterEvents().then(()=>renderMarkers()),300000);$('#fire-toggle').setAttribute('aria-pressed',String(fireVisible));$('#fire-toggle').onclick=()=>{fireVisible=!fireVisible;saveFilters();$('#fire-toggle').setAttribute('aria-pressed',String(fireVisible));drawFireLayer()};refreshFire();setInterval(()=>{if(!document.hidden)refreshFire()},15*60*1000);const id=new URL(location.href).searchParams.get('place');if(id==='__openplans')renderFeed();else if(id)selectPlace(id)}catch(error){console.error(error);$('#result-count').textContent='Destinations couldn’t load';$('#results').innerHTML='<div class="empty">The field guide couldn’t load. <button onclick="location.reload()">Try again</button></div>'}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'search_outzide_places',title:'Search Outzide',description:'Filter the visible Outzide destination list by search text, region and type.',inputSchema:{type:'object',properties:{query:{type:'string'},region:{enum:['OR','WA','all']},kind:{enum:['all','trail','stay','beach','camp','spring','watercamp','coastcamp','fishing','boating','atv','dayuse','winter']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','region','kind'].includes(k))||input.query!=null&&typeof input.query!=='string'||input.region&&!['OR','WA','all'].includes(input.region)||input.kind&&!['all','trail','stay','beach','camp','spring','watercamp','coastcamp','fishing','boating','atv','dayuse','winter'].includes(input.kind))throw Error('Invalid search parameters');state.browseRegion=null;state.activities=[];Object.assign(state,input);$('#search').value=state.query;closeDetail({clear:true});renderList();fitRegion();return {count:filtered().length,places:filtered().map(p=>({id:p.id,name:p.name,kind:p.kind,state:p.state}))}}},{name:'open_outzide_place',title:'Open a destination card',description:'Open the destination detail card and focus its waypoint and mapped trail.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.id!=='string'||Object.keys(input).some(k=>k!=='id')||!places.some(p=>p.id===input.id))throw Error('Unknown destination');selectPlace(input.id);return {id:state.selected.id,name:state.selected.name,cardOpen:$('#detail').open,routeVisible:routeLayers.length>0}}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
const social = new Map();
async function api(path,method='GET',body){
 const response=await fetch('/api/outz/'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});
 const data=response.status===204?null:await response.json();
 if(!response.ok)throw Error(response.status===401?'Sign in from the Zaylist account menu to join in.':data?.error||'Could not save. Please try again.');
 return data;
}
async function refreshDetails(id){
 try{const fresh=await api('details?place='+encodeURIComponent(id));details[id]={...details[id],...fresh,liveForecast:!fresh.forecastUnavailable};if(state.selected?.id===id&&state.tab!=='community'){renderDetail();updateElevation()}}catch{}
}
async function loadCommunity(id){
 if(id==='rooster-rock'||id==='sauvie-island')return;
 const query='?place='+encodeURIComponent(id);
 const date=state.tripDates?.[0]||today();
 try{
  const [posts,rating,checkins,chat]=await Promise.all([api('wall'+query),api('rating'+query),Promise.all((state.tripDates||[date]).map(day=>api('checkins'+query+'&date='+day))).then(rows=>rows.flat()),api('chat'+query).catch(()=>({chatOpen:false,messages:[]}))]);
  social.set(id,{posts,rating,checkins,chat,date});
  if(state.selected?.id===id&&state.tab==='community')renderDetail();
 }catch(error){social.set(id,{error:error.message});if(state.selected?.id===id&&state.tab==='community')renderDetail()}
}
function communityHtml(p){
 if(p.special)return `<h3>${esc(p.name)} community</h3><p>Use the original beach community for your check-ins, beach chat and carpools.</p><a class="primary" href="/outz/${esc(p.id)}" target="_top">Open beach community ↗</a>`;
 const data=social.get(p.id);
 if(!data)return '<p role="status">Loading destination community…</p>';
 if(data.error)return `<p role="alert">${esc(data.error)}</p><button data-live-refresh>Try again</button>`;
 const dates=state.tripDates||[today()],hours=Array.from({length:16},(_,i)=>i+7);
 return `<h3>Check in. You’re in the chat.</h3><p>Plan your visit for the next seven days. Anonymous check-ins keep your identity private and do not unlock chat.</p>
 <form id="checkin-form"><div class="form-grid"><label class="wide">Trip day<div class="inline-form"><input id="trip-date" type="date" value="${dates[dates.length-1]}" min="${today()}" required><button type="button" data-action="add-date">Add day</button></div></label><label>Arriving<select name="arrival">${hours.slice(0,-1).map(h=>`<option value="${h}" ${h===10?'selected':''}>${h}:00</option>`).join('')}</select></label><label>Leaving<select name="departure">${hours.slice(1).map(h=>`<option value="${h}" ${h===13?'selected':''}>${h}:00</option>`).join('')}</select></label><label class="wide">Trip note<input name="note" maxlength="80"></label></div><div class="date-chips">${dates.map(day=>`<button type="button" data-remove-date="${day}">${formatDate(day)} ×</button>`).join('')}</div><label class="check-row"><input type="checkbox" name="anonymous">Check in anonymously</label><button class="primary">Check in</button></form>
 ${faceStackHtml(data.checkins.filter(r=>!r.masked&&!r.isAnonymous),data.checkins.filter(r=>!r.masked&&!r.isAnonymous).length)}<div>${data.checkins.map(r=>`<div class="checkin-record"><strong>${esc(r.isMine?'You':r.displayName||r.username)} · ${formatDate(r.calendarDate)}</strong><small>${r.arrivalHour}:00–${r.departHour}:00 · ${esc(r.note||'')}</small>${r.isMine?`<button data-live-uncheck="${r.id}">Remove check-in</button>`:''}</div>`).join('')}</div>
 <h3>${esc(p.name)} · Chat</h3><div class="chat-box">${data.chat.chatOpen?(data.chat.messages.map(m=>`<p><strong>${esc(m.displayName||m.username||'You')}</strong> ${esc(m.body)}</p>`).join('')||'<p>You’re in. Say hello.</p>'):'<p>Check in with your profile to enter the group chat.</p>'}</div>${data.chat.chatOpen?'<form id="chat-form" class="inline-form"><input name="message" maxlength="500" placeholder="Say hi…" required aria-label="Chat message"><button>Send</button></form>':''}
 <h3>How was your trip?</h3><div class="stars" role="group" aria-label="Rate this trip">${[1,2,3,4,5].map(n=>`<button data-live-rating="${n}" aria-label="${n} out of 5 stars" aria-pressed="${(data.rating.mine||0)>=n}">★</button>`).join('')}</div><p>${data.rating.average==null?'No ratings yet':data.rating.average.toFixed(1)+' / 5 · '+data.rating.count+' ratings'}</p>
 <h3>Trip wall</h3><form id="post-form" class="post-composer"><label>Post type<select name="kind">${['TRIP_NOTE','LOOKING_FOR_COMPANY','HIKE_BUDDY','CAMP_BUDDY','CARPOOL_OFFER','CARPOOL_REQUEST'].map(k=>`<option value="${k}">${esc(feedLabels[k])}</option>`).join('')}</select></label><label>Trip day<input name="date" type="date" value="${dates[0]}" min="${today()}"></label><textarea name="body" maxlength="500" required aria-label="Trip wall post" placeholder="Share a plan, ride or trail note…"></textarea><button class="primary">Post to wall</button></form>${data.posts.map(livePostHtml).join('')||'<p>No posts yet.</p>'}`;
}
function livePostHtml(post,{feedRow=false}={}){return `<article class="post">${feedRow?'':`<header><strong>${esc(post.author||post.displayName||post.username||'Community')}</strong><span>${esc(feedLabels[post.postKind]||post.postKind||'Trail note')}</span></header>`}<p>${esc(post.body)}</p><small>${post.tripDate?formatDate(post.tripDate):'Dates flexible'}</small>${post.isMine?`<div class="post-actions"><button data-live-edit="${post.id}">Edit</button><button data-live-delete="${post.id}">Remove my post</button></div>`:''}${state.editPost===Number(post.id)?`<form data-live-edit-form="${post.id}"><textarea name="body" maxlength="500" required>${esc(post.body)}</textarea><button>Save changes</button></form>`:''}${(post.comments||[]).map(c=>`<p class="reply"><strong>${esc(c.displayName||c.username)}</strong> ${esc(c.body)}</p>`).join('')}<form class="inline-form" data-live-reply="${post.id}"><input name="body" maxlength="300" required aria-label="Reply to post" placeholder="Reply…"><button>Reply</button></form></article>`}
async function refreshFeed(){
 try{feed=await api('feed');if(!$('#trail-feed').hidden)renderFeedItems()}
 catch(error){if(!$('#trail-feed').hidden)renderFeedItems()}
}
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&e.target.closest('.field-avatar'))e.target.remove();},true);
function renderFeedItems(){
 const target=$('#field-feed-items');if(!target)return;
 const demo=!(feed.items||[]).length;$('.feed-local-note').textContent=demo?'Demo feed · Fictional examples, not live plans, check-ins or conditions. Sign in to create real posts.':'Posts are shared with the Outzide community. Sign in to post or reply.';const items=(demo?demoFeedItems():feed.items).map(item=>({...item,filterKind:item.postKind||item.kind})).filter(item=>state.feedKind==='all'||item.filterKind===state.feedKind||(state.feedKind==='CARPOOL'&&/carpool/i.test(item.filterKind))||(state.feedKind==='TRIP_NOTE'&&item.filterKind==='post'));
 items.sort((a,b)=>feedSort==='trip'?(a.tripDate||'9999').localeCompare(b.tripDate||'9999'):(b.createdAt||'').localeCompare(a.createdAt||''));
 target.innerHTML=items.map(item=>{const place=places.find(p=>p.id===item.placeId||(item.demo&&p.name===item.placeName));const destination=place?`<button class="field-place-link" data-field-place="${esc(place.id)}">⌖ ${esc(place.name)}</button>`:item.placeId==='__openplans'?'<p>Destination open · decide together</p>':`<p>${esc(item.placeName||'Northwest')}</p>`;return `<div class="field-post">${feedIdentity(item,feedLabels[item.filterKind]||item.title)}${destination}${item.id?.startsWith('post:')?livePostHtml({...item,id:Number(item.id.slice(5))},{feedRow:true}):`<h3>${esc(item.title)}</h3><p>${esc(item.body)}</p>${item.href?link(new URL(item.href,location.origin).href,'View details'):''}`}</div>`}).join('')||'<div class="field-feed-empty"><strong>No posts here yet.</strong><p>Share a trail note, find a buddy, or arrange a ride.</p></div>';
}
let mutationPending=false;
async function mutate(action){
 if(mutationPending)return;mutationPending=true;
 try{await action();refreshMapCheckins();toast('Saved to Outzide.');state.editPost=null;await Promise.all([state.selected&&!state.selected.special?loadCommunity(state.selected.id):Promise.resolve(),refreshFeed()])}
 catch(error){toast(error.message)}finally{mutationPending=false}
}
document.addEventListener('change',e=>{if(e.target.id==='trip-date'){if(state.selected)loadCommunity(state.selected.id)}});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-live-refresh'))loadCommunity(state.selected.id);
 if(b.dataset.liveRating)mutate(()=>api('rating','POST',{placeId:state.selected.id,rating:Number(b.dataset.liveRating)}));
 if(b.dataset.liveUncheck)mutate(()=>api('checkins/'+b.dataset.liveUncheck,'DELETE'));
 if(b.dataset.liveDelete)mutate(()=>api('wall/'+b.dataset.liveDelete,'DELETE'));
 if(b.dataset.liveEdit){state.editPost=Number(b.dataset.liveEdit);if(state.tab==='community')renderDetail();renderFeedItems()}
});
document.addEventListener('submit',e=>{
 const form=e.target;
 if(!['field-feed-compose','checkin-form','chat-form','post-form'].includes(form.id)&&!form.dataset.liveReply&&!form.dataset.liveEditForm)return;
 e.preventDefault();const data=new FormData(form),body=String(data.get('body')||'').trim(),placeId=state.selected?.id;
 mutate(async()=>{
  if(form.id==='checkin-form')await api('checkins','POST',{placeId,dates:[...new Set([...(state.tripDates||[]),document.querySelector('#trip-date').value])],arrivalHour:Number(data.get('arrival')),departHour:Number(data.get('departure')),note:data.get('note'),isAnonymous:data.has('anonymous')});
  else if(form.id==='chat-form')await api('chat','POST',{placeId,date:state.tripDates?.[0]||today(),body:String(data.get('message')||'').trim()});
  else if(form.dataset.liveReply)await api('wall/'+form.dataset.liveReply+'/comments','POST',{body});
  else if(form.dataset.liveEditForm)await api('wall/'+form.dataset.liveEditForm,'PATCH',{body});
  else {const destination=form.id==='field-feed-compose'?String(data.get('place')||'__openplans'):placeId;const extra=[data.get('area')?'Area: '+data.get('area'):'',data.get('departure')?'Leaving from: '+data.get('departure'):''].filter(Boolean);await api('wall','POST',{placeId:destination,postKind:data.get('kind'),tripDate:data.get('date')||null,body:[body,...extra].join('\n')});}
  if(form.elements.body)form.elements.body.value='';if(form.elements.message)form.elements.message.value='';
 });
});

setInterval(()=>{if(!document.hidden&&!$('#trail-feed').hidden)refreshFeed()},60000);
init();

// Same compact key interaction as Mapz; Escape returns focus to its trigger.
$('#map-key-toggle').onclick=()=>{const open=$('#map-key').hidden;$('#map-key').hidden=!open;$('#map-key-toggle').setAttribute('aria-expanded',String(open));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#map-key').hidden&&!$('#detail').open&&!$('#utility').open){$('#map-key').hidden=true;$('#map-key-toggle').setAttribute('aria-expanded','false');$('#map-key-toggle').focus();}});

const mapCheckins=new Map();
async function refreshMapCheckins(){try{const rows=await api('map-checkins');mapCheckins.clear();for(const row of rows)mapCheckins.set(row.placeId,row);renderMarkers();}catch{mapCheckins.clear();renderMarkers();}}
refreshMapCheckins();setInterval(()=>{if(!document.hidden)refreshMapCheckins()},60000);
installMobileDrawer($('#detail'),()=>closeDetail(),'destination card');
let browseDraft={region:null,activities:[]};
const browsePanel=document.createElement('section');browsePanel.id='browse-steps';browsePanel.hidden=true;$('.discovery').prepend(browsePanel);
const browseSummary=document.createElement('div');browseSummary.id='browse-summary';$('.discovery .search').before(browseSummary);
function renderBrowseSummary(){if(!browseSummary)return;const r=browseRegions.find(r=>r.id===state.browseRegion);browseSummary.hidden=!r;browseSummary.innerHTML=r?'<span class="eyebrow">3 / 3 · YOUR DESTINATIONS</span><strong>'+esc(r.name)+'</strong><small>'+esc(state.activities.map(k=>kinds[k]).join(' · ')||'All activities')+'</small><button type="button" data-browse-edit>Change choices</button>':'';}
function showBrowseStep(step){
 $('.discovery').classList.toggle('choosing-spots',step!=='results');browsePanel.hidden=step==='results';
 if(step==='results'){renderBrowseSummary();$('.discovery .search input').focus();return;}
 const region=browseRegions.find(r=>r.id===browseDraft.region);
 browsePanel.innerHTML='<header><span class="eyebrow">'+(step==='region'?'1 / 3 · CHOOSE YOUR AREA':'2 / 3 · CHOOSE YOUR ACTIVITIES')+'</span><button type="button" data-browse-close aria-label="Close browse spots">×</button></header><h2 tabindex="-1">'+(step==='region'?'What region?':'What would you like to do?')+'</h2><p>'+(step==='region'?'Choose a corner of the Northwest.':esc(region.name)+' · Select one or more activities.')+'</p>'+(step==='region'?'<div class="browse-regions">'+browseRegions.map(r=>'<button type="button" data-browse-region="'+r.id+'" aria-pressed="'+(browseDraft.region===r.id)+'"><strong>'+esc(r.name)+'</strong><small>'+esc(r.note)+'</small></button>').join('')+'</div>':'<form id="browse-activities"><div class="browse-activities">'+Object.entries(kinds).map(([k,label])=>{const count=places.filter(p=>browseRegionFor(p)===browseDraft.region&&p.kind===k).length;return '<label><input type="checkbox" name="activity" value="'+k+'" '+(browseDraft.activities.includes(k)?'checked':'')+'>'+icon(k)+'<span>'+esc(label)+'</span><small>'+count+'</small></label>';}).join('')+'</div><footer><button type="button" data-browse-back>← Region</button><button class="primary" type="submit" '+(!browseDraft.activities.length?'disabled':'')+'>Show destinations</button></footer></form>');
 browsePanel.querySelector('h2').focus();
 const form=$('#browse-activities');if(form){enhanceActivitySelection(form,kinds);form.onchange=()=>{browseDraft.activities=[...form.querySelectorAll('input:checked')].map(i=>i.value);form.querySelector('[type="submit"]').disabled=!browseDraft.activities.length;};form.onsubmit=e=>{e.preventDefault();if(!browseDraft.activities.length)return;state.browseRegion=browseDraft.region;state.activities=[...browseDraft.activities];state.kind='all';state.region='all';state.query='';$('#search').value='';closeDetail({clear:true});showBrowseStep('results');renderList();const rows=filtered();if(rows.length&&map){const b=new maplibregl.LngLatBounds();rows.forEach(p=>b.extend([p.lng,p.lat]));map.fitBounds(b,{padding:window.innerWidth>760?{left:420,right:90,top:170,bottom:80}:60,maxZoom:11,duration:0});}$('#result-count').textContent=rows.length+' matching destinations';};}
}
function openBrowse(){browseDraft={region:state.browseRegion,activities:[...(state.activities.length?state.activities:state.kind==='all'?[]:[state.kind])]};closeDetail({clear:true});setView('list');showBrowseStep('region');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-browse-region')){browseDraft.region=b.dataset.browseRegion;showBrowseStep('activities');}if(b.hasAttribute('data-browse-back'))showBrowseStep('region');if(b.hasAttribute('data-browse-edit'))openBrowse();if(b.hasAttribute('data-browse-close')){showBrowseStep('results');setView('map');$('.browse-toggle').focus();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!browsePanel.hidden){showBrowseStep('results');setView('map');$('.browse-toggle').focus();}});

function closurePanel(p){const row=closureFor(p.id);return '<section class="closure-card '+(isClosed(p.id)?'is-closed':'')+'" data-closure-card="'+esc(p.id)+'" aria-live="polite"><strong>'+ (isClosed(p.id)?prohibitionIcon:'')+esc(closureLabel(p.id))+'</strong>'+(p.kind==='winter'&&row?.status!=='open'?'<p class="winter-opening-date">'+esc(winterOpeningLabel(p.id))+' · Subject to snow and conditions.</p>':'')+'<p>'+(row?'Checked '+stamp(row.checkedAt)+'. Source does not provide an observation time.':'No current verified status is available. Check the official operator before visiting.')+'</p>'+(row?link(row.sourceUrl,'Official status'):link(p.officialUrl||p.url||'https://www.fs.usda.gov','Check operator'))+'</section>';}
async function updateClosures(){await refreshClosures();renderMarkers();$$('[data-closure-card]').forEach(el=>{const p=places.find(p=>p.id===el.dataset.closureCard);if(p)el.outerHTML=closurePanel(p);});}
updateClosures();setInterval(()=>{if(!document.hidden)updateClosures();},60_000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClosures();});

function renderActiveMapFilters(count){
 const target=$('#active-map-filters'),chips=[];
 if(state.region!=='all')chips.push(['region',state.region==='OR'?'Oregon':'Washington']);
 if(state.browseRegion)chips.push(['browse',browseRegions.find(r=>r.id===state.browseRegion)?.name||'Region']);
 for(const kind of state.activities.length?state.activities:state.kind==='all'?[]:[state.kind])chips.push(['kind:'+kind,kinds[kind]]);
 if(state.query)chips.push(['query','“'+state.query+'”']);
 $('#matching-count').textContent=count;
 $('#matching-count').setAttribute('aria-label',count+' matching spots');
 target.hidden=!chips.length;
 target.innerHTML=chips.length?chips.map(([key,label])=>'<button type="button" data-remove-filter="'+esc(key)+'" aria-label="Remove '+esc(label)+' filter">'+esc(label)+' <span aria-hidden="true">×</span></button>').join('')+'<button type="button" data-remove-filter="all">Clear all</button>':'';
 $('#reset-filters').hidden=!chips.length;
 $('#map-key').innerHTML=Object.entries(kinds).filter(([kind])=>kind!=='all').map(([kind,label])=>'<span style="--key-color:'+esc(places.find(p=>p.kind===kind)?.accent||'#eeeae0')+'">'+icon(kind)+'<span>'+esc(label)+'</span></span>').join('');
}
$('#active-map-filters').onclick=e=>{const b=e.target.closest('[data-remove-filter]');if(!b)return;const key=b.dataset.removeFilter;
 if(key==='all'){resetFilters();}else{if(key==='region')state.region='all';if(key==='browse')state.browseRegion=null;if(key==='query'){state.query='';$('#search').value='';}if(key.startsWith('kind:')){state.activities=state.activities.filter(k=>k!==key.slice(5));state.kind='all';}closeDetail({clear:true});renderList();}
 const next=$('#active-map-filters button');if(next)next.focus();else $('.browse-toggle').focus();
};

// Browse remains a nonmodal map sheet: the handle supports tap, keyboard and drag.
const browseHandle=document.createElement('button');browseHandle.className='browse-drawer-handle';browseHandle.type='button';browseHandle.setAttribute('aria-controls','outz-browse-content');
$('.discovery').id='outz-browse-content';$('.discovery').prepend(browseHandle);
let browseStart=null,browseDragged=false;
function syncBrowseHandle(){const open=state.view==='list';browseHandle.innerHTML='<span>'+(open?'Back to map':'Browse spots')+'</span><i aria-hidden="true"></i>';browseHandle.setAttribute('aria-expanded',String(open));$('.discovery').querySelectorAll('input,button,a,select').forEach(el=>{if(el!==browseHandle)el.inert=matchMedia('(max-width:760px)').matches&&!open;});}
new MutationObserver(syncBrowseHandle).observe($('.workspace'),{attributes:true,attributeFilter:['class']});window.addEventListener('resize',syncBrowseHandle);syncBrowseHandle();
browseHandle.onclick=()=>{if(browseDragged){browseDragged=false;return;}if(state.view==='list')setView('map');else openBrowse();};
browseHandle.onpointerdown=e=>{if(e.button!==0)return;browseStart=e.clientY;browseDragged=false;browseHandle.setPointerCapture(e.pointerId);};
browseHandle.onpointerup=e=>{if(browseStart===null)return;const delta=e.clientY-browseStart;browseStart=null;browseDragged=Math.abs(delta)>12;if(delta>32)setView('map');else if(delta< -32)openBrowse();};
browseHandle.onpointercancel=()=>{browseStart=null;browseDragged=true;};
